	Add(KELA_SETTINGS_FEATURES_BASE_GAME_FIXES, "U51 BG-Korrekturen", 0)
	Add(KELA_SETTINGS_FEATURES_BASE_GAME_FIXES_TOOLTIP, "Behebt drei Probleme mit dem U51-Schlachtfeld-Gamepad: L2/R2 blättern jetzt durch die Zusammenfassungen der Kampfrunden auf der Schlachtfeld-Anzeigetafel, die 6v6v6- und 9v9-Anzeigetafelzeilen überlappen nicht mehr ihre Teamfelder und der Aktivitätsfinder-Schlachtfeldeintrag wird freigeschaltet, sobald seine Daten geladen werden, anstatt nach dem Zurücksetzen und erneuten Betreten. Diese Spiegel-ZOS-Korrekturen; Deaktivieren Sie diese Option oder löschen Sie kpui_basegame_fixes.lua, sobald das Spielupdate sie ausliefert.", 0)
