	Add(KELA_SETTINGS_FIXES_GROUP_MENU_TOOLTIP, "Verhindert, dass die leere Mitgliederliste und das Hintergrundfeld des Gamepad-Gruppenmenüs während des Spielens über dem HUD angezeigt werden. Das Spiel hängt dieses Panel an die aktuelle Szene an, wenn das Gruppenmenü seine Liste neu aufbaut, auch wenn das Menü geschlossen ist; Dadurch bleibt es nur dem Gruppenmenü zugeordnet.", 0)
	Add(KELA_SETTINGSYSTEMPANEL7700, "Kontoweite Einstellungen", 0)
